	SELECT [UpdateDT], @NewWorkspaceID, [Year], [Escalation], [MiscRate], [PerDiemRate]
	FROM [dbo].[WorkspaceRMSTravelEscalationRate] WHERE [WorkspaceID] = @CopyFromWorkspaceID

--RAISERROR ('Error raised in TRY block.', -- Message text.
--               16, -- Severity.
--               1 -- State.
--               );

IF @@ERROR = 0
	BEGIN
		COMMIT TRANSACTION

		/*Workspace Copy Metric*/
		IF @CopyFromWorkspaceID IS NOT NULL 
		BEGIN

		DECLARE @CreateDate datetime2(7) = GetDate()

		INSERT INTO [dbo].[WorkspaceCopySource]
           ([WorkspaceID]
           ,[UpdateDT]
           ,[WorkspaceName]
           ,[WorkspaceShortName]
           ,[WorkspaceStateID]
           ,[ContractStartDate]
           ,[ContractEndDate]
           ,[ProposalSubmitDate]
           ,[WorkspaceDescription]
           ,[CostVolumeLeadPricerUserID]
           ,[RFPNumber]
           ,[TemplateID]
           ,[ContainsOCI]
           ,[CreatedByETIUserID]
           ,[AllowSearch]
           ,[ResourceListID]
           ,[PerformingOrganizationListID]
           ,[PerformingOrganizationChangeFlag]
           ,[TrackingNumber]
           ,[ContainsTemplate]
           ,[NumProPricerExport]
           ,[ProposalStatusID]
           ,[StatusComment]
           ,[BOEExportSortByID]
           ,[SegmentID]
           ,[LineOfBusinessID]
           ,[ProposalClassID]
           ,[ProposalTitle]
           ,[IsDeleted]
           ,[DateDeleted]
		   ,[LineOfBusinessName]
		   ,[NumOfBOEs]
		   ,[CreateDate]
		   )

	SELECT W.[WorkspaceID]
		  ,W.[UpdateDT]
		  ,W.[WorkspaceName]
		  ,W.[WorkspaceShortName]
		  ,W.[WorkspaceStateID]
		  ,W.[ContractStartDate]
		  ,W.[ContractEndDate]
		  ,W.[ProposalSubmitDate]
		  ,W.[WorkspaceDescription]
		  ,W.[CostVolumeLeadPricerUserID]
		  ,W.[RFPNumber]
		  ,W.[TemplateID]
		  ,W.[ContainsOCI]
		  ,W.[CreatedByETIUserID]
		  ,W.[AllowSearch]
		  ,W.[ResourceListID]
		  ,W.[PerformingOrganizationListID]
		  ,W.[PerformingOrganizationChangeFlag]
		  ,W.[TrackingNumber]
		  ,W.[ContainsTemplate]
		  ,W.[NumProPricerExport]
		  ,W.[ProposalStatusID]
		  ,W.[StatusComment]
		  ,W.[BOEExportSortByID]
		  ,W.[SegmentID]
		  ,W.[LineOfBusinessID]
		  ,W.[ProposalClassID]
		  ,W.[ProposalTitle]
		  ,W.[IsDeleted]
		  ,W.[DateDeleted]
		  ,LOB.[LineOfBusinessName]	      
		  ,(SELECT COUNT (*) FROM [dbo].[BOE] WHERE WorkspaceID = @CopyFromWorkspaceID) AS [NumOfBOEs]
		  ,@CreateDate
	  FROM [dbo].[Workspace] W
		LEFT OUTER JOIN [dbo].[LineOfBusiness] LOB ON W.LineOfBusinessID = LOB.LineOfBusinessID
	  WHERE WorkspaceID = @CopyFromWorkspaceID



		INSERT INTO [dbo].[WorkspaceCopyTarget]
           ([WorkspaceID]
           ,[UpdateDT]
           ,[WorkspaceName]
           ,[WorkspaceShortName]
           ,[WorkspaceStateID]
           ,[ContractStartDate]
           ,[ContractEndDate]
           ,[ProposalSubmitDate]
           ,[WorkspaceDescription]
           ,[CostVolumeLeadPricerUserID]
           ,[RFPNumber]
           ,[TemplateID]
           ,[ContainsOCI]
           ,[CreatedByETIUserID]
           ,[AllowSearch]
           ,[ResourceListID]
           ,[PerformingOrganizationListID]
           ,[PerformingOrganizationChangeFlag]
           ,[TrackingNumber]
           ,[ContainsTemplate]
           ,[NumProPricerExport]
           ,[ProposalStatusID]
           ,[StatusComment]
           ,[BOEExportSortByID]
           ,[SegmentID]
           ,[LineOfBusinessID]
           ,[ProposalClassID]
           ,[ProposalTitle]
           ,[IsDeleted]
           ,[DateDeleted]
		   ,[LineOfBusinessName]
		   ,[NumOfBOEs]
		   ,[CreateDate]
		   )

	SELECT W.[WorkspaceID]
		  ,W.[UpdateDT]
		  ,W.[WorkspaceName]
		  ,W.[WorkspaceShortName]
		  ,W.[WorkspaceStateID]
		  ,W.[ContractStartDate]
		  ,W.[ContractEndDate]
		  ,W.[ProposalSubmitDate]
		  ,W.[WorkspaceDescription]
		  ,W.[CostVolumeLeadPricerUserID]
		  ,W.[RFPNumber]
		  ,W.[TemplateID]
		  ,W.[ContainsOCI]
		  ,W.[CreatedByETIUserID]
		  ,W.[AllowSearch]
		  ,W.[ResourceListID]
		  ,W.[PerformingOrganizationListID]
		  ,W.[PerformingOrganizationChangeFlag]
		  ,W.[TrackingNumber]
		  ,W.[ContainsTemplate]
		  ,W.[NumProPricerExport]
		  ,W.[ProposalStatusID]
		  ,W.[StatusComment]
		  ,W.[BOEExportSortByID]
		  ,W.[SegmentID]
		  ,W.[LineOfBusinessID]
		  ,W.[ProposalClassID]
		  ,W.[ProposalTitle]
		  ,W.[IsDeleted]
		  ,W.[DateDeleted]
		  ,LOB.[LineOfBusinessName]	    
		  ,(SELECT COUNT (*) FROM [dbo].[BOE] WHERE WorkspaceID = @NewWorkspaceID) AS [NumOfBOEs]
		  ,@CreateDate
	  FROM [dbo].[Workspace] W
		LEFT OUTER JOIN [dbo].[LineOfBusiness] LOB ON W.LineOfBusinessID = LOB.LineOfBusinessID
 WHERE WorkspaceID = @NewWorkspaceID


	INSERT INTO [dbo].[WorkspaceCopyMetric]
           ([SourceWorkspaceID]
           ,[TargetWorkspaceID]
           ,[CreateDate])
     VALUES
           (@CopyFromWorkspaceID
           ,@NewWorkspaceID
           ,@CreateDate)

		
		END

		SELECT @NewWorkspaceID AS WorkspaceID
	END

END TRY


BEGIN CATCH
	ROLLBACK TRANSACTION
	

	DECLARE @ErrorMessage varchar (500)
	SELECT @ErrorMessage = ERROR_MESSAGE()
	RAISERROR (
			@ErrorMessage, -- Message text.
	        11, -- Severity,/*Severity Changed to 11*/
			1 -- State,
			)


		
	RETURN
	
END CATCH
GO

