INSERT INTO [version].[Trip]
           ([TripID]
           ,[UpdateDT]
           ,[TravelMiscRateID]
           ,[DepartureLocationID]
           ,[DestinationLocationID]
           ,[PerDiemID]
           ,[TransportationFare]
           ,[RoundTripMiles]
           ,[FareLastUpdateDT]
           ,[FareLastUpdateETIUserID]
           ,[TripInUse]
           ,[LastUsedDT]
/*WI8256           ,[LockedRate]*/
           ,[VersionID]
/*WI8256           ,[Year]
           ,[DevEscalation]
           ,[LMSIEscalation]*/
           ,[RentalCarRate]
           ,[DestinationLocationCode]
           ,[DepartureLocationCode]
           )
SELECT T.[TripID]
      ,T.[UpdateDT]
      ,T.[TravelMiscRateID]
      ,T.[DepartureLocationID]
      ,T.[DestinationLocationID]
      ,T.[PerDiemID]
      ,T.[TransportationFare]
      ,T.[RoundTripMiles]
      ,T.[FareLastUpdateDT]
      ,T.[FareLastUpdateETIUserID]
      ,T.[TripInUse]
      ,T.[LastUsedDT]
/*WI8256      ,T.[LockedRate]*/
      ,@VersionID
/*WI8256      ,T.[Year]
      ,T.[DevEscalation]
      ,T.[LMSIEscalation]*/
      ,T.[RentalCarRate]
      ,T.[DestinationLocationCode]
      ,T.[DepartureLocationCode]
