		,tt.[ModeID]
		,tt.[TravelTripTaskElementID]
		,tt.[UpdateDT]
		,tt.[GroupID]
		,tt.[SegmentID]
		,tt.[Purpose]
		,tt.[PerformingOrganizationID]
		,tt.[TripDate]
		,tt.[EstimateDate]
		,tt.[NumPeople]
		,tt.[NumDays]
		,tt.[ZoneOriginID]
		,tt.[ZoneDestCity]
		,tt.[ZoneDestinationID]
		,tt.[ZoneResourceID]
		,tt.[NonZoneFrom]
		,tt.[NonZoneTo]
