CREATE PROCEDURE [dbo].[deleteWorkspace]
(
@WorkspaceID int,
@UpdateDT datetime2
)
AS
/******************************************************************************
**		 
**		Name: [deleteWorkspace]
**		Desc: Delete Workspace 
**			
**		
**
**		Auth: Don Canuso
**		Date: 01/10/12
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			---------------------------------------
**		8/21/13		dcanuso				workspace can have multiple 
**										contract types
**		8/27/14		dcanuso				Image Story
