		WS.WorkspaceID AS WorkspaceID,
		WSR.RoleID AS WorkspaceRoleID,
		WS.WorkspaceStateID AS WorkspaceStateID
	FROM dbo.Workspace WS
		INNER JOIN dbo.WorkspaceUserRole WSR ON WS.WorkspaceID = WSR.WorkspaceID
