BEGIN

DECLARE @CreateDate datetime2(7) = GetDate()

INSERT INTO [dbo].[BOECopySource]
           ([BOEID]
           ,[UpdateDT]
           ,[BOEStateID]
           ,[BOEStartDate]
           ,[BOEEndDate]
           ,[BOEDescription]
           ,[DataSource]
