  FROM [dbo].[BOE] B
	INNER JOIN [dbo].[Workspace] W ON B.WorkspaceID = W.WorkspaceID
  WHERE B.BOEID = @CopyFromBOEID

INSERT INTO [dbo].[BOECopyTarget]
           ([BOEID]
           ,[UpdateDT]
           ,[BOEStateID]
           ,[BOEStartDate]
           ,[BOEEndDate]
           ,[BOEDescription]
           ,[DataSource]
           ,[WorkspaceID]
           ,[MetricDisclosureAcknowledge]
           ,[NumAuthorReassigned]
           ,[IsMaterial]
           ,[BOETitle]
		   ,[WorkspaceName]
		   ,[WorkspaceShortName]
		   ,[CreateDate]
		   )
SELECT B.[BOEID]
      ,B.[UpdateDT]
      ,B.[BOEStateID]
      ,B.[BOEStartDate]
      ,B.[BOEEndDate]
      ,B.[BOEDescription]
      ,B.[DataSource]
      ,B.[WorkspaceID]
      ,B.[MetricDisclosureAcknowledge]
      ,B.[NumAuthorReassigned]
      ,B.[IsMaterial]
      ,B.[BOETitle]
	  ,W.[WorkspaceName]
	  ,W.[WorkspaceShortName]
	  ,@CreateDate
  FROM [dbo].[BOE] B
	INNER JOIN [dbo].[Workspace] W ON B.WorkspaceID = W.WorkspaceID
 WHERE B.BOEID = @BOEID


INSERT INTO [dbo].[BOECopyMetric]
           ([SourceBOEID]
           ,[TargetBOEID]
           ,[CreateDate])
     VALUES
           (@CopyFromBOEID
           ,@BOEID
           ,@CreateDate)



END

