			   (
			   @UpdateDT,
			   @WorkspaceID,
			   @FormName,
			   @Description,
			   @BasisAndRationale,
			   @ProposalTitle,
			   @ProposalDate,
			   @Poc,
			   @PocPhone,
			   @Approver,
			   @ApproverPhone,
			   @BusinessArea,
			   0, -- Revision always starts at 0
			   @FormVersion
			   )
		SELECT @IBOEFormID = IBOEID FROM @InsertedIBOE
	
		IF EXISTS (SELECT * FROM @Resources)
			BEGIN 
				INSERT INTO [dbo].[BOEFormIBOEResourcesXREF]
				   ([IBOEFormID]
				   ,[ResourceID]
				   )
				 SELECT
				   @IBOEFormID,
				   ResourceID
				   FROM @Resources
			END	

		IF EXISTS (SELECT * FROM @Clins)
			BEGIN 
				INSERT INTO [dbo].[BOEFormIBOECLINsXREF]
				   ([IBOEFormID]
				   ,[ClinID]
				   ,[ContractType]
				   )
				 SELECT
				   @IBOEFormID,
				   [ClinID],
				   [ContractType]
				   FROM @Clins
			END	
	END	
ELSE
	/*Update*/
	BEGIN
		IF (SELECT UpdateDT FROM [dbo].[BOEFormIBOE] WHERE [IBOEFormID] = @IBOEFormID) = @UpdateDT
			BEGIN			
				SET @UpdateDT = GETDATE()				
				UPDATE [dbo].[BOEFormIBOE]
					SET 
						[UpdateDT] = @UpdateDT,
						[FormName] = @FormName,
						[Description] = @Description,
						[BasisAndRationale] = @BasisAndRationale,
						[ProposalTitle] = @ProposalTitle,
						[ProposalDate] = @ProposalDate,
						[Poc] = @Poc,
						[PocPhone] = @PocPhone,
						[Approver] =@Approver,
