SET NOCOUNT ON 
DECLARE @InsertedBOEPotentialRole AS Table (BOEPotentialRoleID int)
DECLARE	@ErrorMessage varchar (500)

IF @BOEPotentialRoleID < 0
BEGIN
/*
genBoeSpace_main
ipecoor2
*/
--SELECT * FROM dbo.BOEPotentialRole BR
--inner join rolelu r on br.roleid =r.RoleID
