				)
			BEGIN
				SET @ErrorMessage =   'There is already a record for this BOE Potential Role'
				RAISERROR (
					@ErrorMessage, -- Message text.
			        11, -- Severity,/*Severity Changed to 11*/
					1 -- State,
					)
				RETURN
			END

	ELSE
	BEGIN
