CREATE PROCEDURE [dbo].[upsertODCType]
(
@ODCTypeID int,
@ResourceID int,
@PerformingOrganizationID int,
@ODCTypeStartDate date,
@ODCTypeEndDate date,
@SpreadCurveID int,
@ODCTypeCost decimal (12,2),
