	*******************************************************************************/
	SET NOCOUNT ON 

	IF @Id  < 0 
		/* Insert */
		BEGIN
			SELECT @Id = MAX(ProposalClassId) + 1 FROM [dbo].ProposalClassLU
			
			INSERT INTO [dbo].ProposalClassLU
						(
							ProposalClassId,
							ProposalClass,
							IsActive
						)
				VALUES
						(
							@Id,
							@Text,
							@IsActive
						)
		END
	ELSE
		/* Update */
		BEGIN
			UPDATE [dbo].ProposalClassLU
			   SET 
					ProposalClass = @Text,
					IsActive = @IsActive
				WHERE 
					ProposalClassID = @Id
		END

	IF @@ERROR = 0
		SELECT @Id AS NewId

GO

