CREATE PROCEDURE [dbo].[insertBOETaskElementCustomFieldValueviaTableParameter]
(
@BOETaskElementCustomFieldValueXREF [dbo].[TT_BOETaskElementCustomFieldValueXREF] READONLY
)
AS
/******************************************************************************
**		 
**		Name: upsertBOETaskElementCustomFieldValue
**		Desc: Insert/Update Custom Field Value for the BOE Task Element
**			
**		
**
**		Auth: Don Canuso
**		Date: 2/14/11
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			----------------------------------------
**		7/20/11		DCANUSO				WI 4215 - Custom Fields are scope specific
**		3/8/18		ranzalon			BOEJ-3079 - Open Ended Custom Fields
**		3/29/18		ranzalon			BOEJ-3268 - Fix copy workspace
*******************************************************************************/
SET NOCOUNT ON 

DECLARE @UpdateDT datetime2(7) = GETDATE()

DECLARE @InsertedValues AS TABLE (CustomFieldValueID int, BTECFVID int)

--Insert Open Ended CFs into CustomFieldValue table and get value IDs
--Only do this for values not already in the db, otherwise this will cause duplicates during copy workspace
MERGE INTO [dbo].[CustomFieldValue] AS cfv
USING @BOETaskElementCustomFieldValueXREF AS xref
ON 1=0
WHEN NOT MATCHED AND xref.IsOpenEnded = 1 AND xref.CustomFieldValueID < 0 THEN 
INSERT 
	([CustomFieldValueName]
	,[CustomFieldValueDescription]
	,[CustomFieldID]
	,[CustomFieldValueInUseFlag]
	,[UpdateDT])
VALUES
	(CONVERT(varchar(10), xref.CustomFieldID) + '-' + CONVERT(varchar(10), xref.BOETaskElementID), --Name only used when performing copy, so it needs to be unique for mapping
	xref.CustomFieldValueDescription,
	xref.CustomFieldID,
	1,
	@UpdateDT)
OUTPUT inserted.CustomFieldValueID, xref.BTECFVID 
INTO @InsertedValues (CustomFieldValueID, BTECFVID);

--Update Open Ended Fields that were already in the db to in use (for copy workspace)
--and then add them to the @InsertedValues table
UPDATE [dbo].[CustomFieldValue]
SET [CustomFieldValueInUseFlag] = 1
WHERE [CustomFieldValueID] in
	(
		SELECT CustomFieldValueID
		FROM @BOETaskElementCustomFieldValueXREF
		WHERE IsOpenEnded = 1 AND CustomFieldValueID > 0
	)

INSERT INTO @InsertedValues
SELECT CustomFieldValueID, BTECFVID
FROM @BOETaskElementCustomFieldValueXREF
WHERE IsOpenEnded = 1 AND CustomFieldValueID > 0

--Insert Open Ended CFs Xrefs
INSERT INTO [dbo].[BOETaskElementCustomFieldValueXREF]
           ([BOETaskElementID]
           ,[CustomFieldValueID]
           ,[UpdateDT])
SELECT
	[BOETaskElementID]
	,iv.CustomFieldValueID
	,@UpdateDT
FROM @BOETaskElementCustomFieldValueXREF xref JOIN @InsertedValues iv 
ON xref.BTECFVID = iv.BTECFVID;

--Insert Standard CFs
INSERT INTO [dbo].[BOETaskElementCustomFieldValueXREF]
           ([BOETaskElementID]
           ,[CustomFieldValueID]
           ,[UpdateDT])
SELECT
           BOETaskElementID,
           CustomFieldValueID,
           @UpdateDT
FROM @BOETaskElementCustomFieldValueXREF
WHERE [IsOpenEnded] = 0            
      
UPDATE dbo.CustomFieldValue
	SET CustomFieldValueInUseFlag = 1
WHERE CustomFieldValueID IN
					
					(
						SELECT CustomFieldValueID
						FROM @BOETaskElementCustomFieldValueXREF
						WHERE IsOpenEnded = 0
					)

DECLARE @ReturnTable AS TABLE (BTECFVID int, UpdateDT Datetime2(7), OrderID int)

INSERT INTO @ReturnTable
SELECT X.BTECFVID AS BTECFVID,
		X.UpdateDT,
		T.OrderID
	FROM [dbo].[BOETaskElementCustomFieldValueXREF] X
		INNER JOIN @BOETaskElementCustomFieldValueXREF T ON
				X.BOETaskElementID = T.BOETaskElementID AND
				X.CustomFieldValueID = T.CustomFieldValueID
	WHERE X.UpdateDT = @UpdateDT

INSERT INTO @ReturnTable
	SELECT X.BTECFVID AS BTECFVID,
		X.UpdateDT,
		T.OrderID
	FROM [dbo].[BOETaskElementCustomFieldValueXREF] X
		INNER JOIN @BOETaskElementCustomFieldValueXREF T ON
				X.BOETaskElementID = T.BOETaskElementID
		INNER JOIN @InsertedValues I ON
				I.CustomFieldValueID = X.CustomFieldValueID
	WHERE X.UpdateDT = @UpdateDT

IF @@ERROR = 0
	SELECT 
		BTECFVID AS BTECFVID,
		UpdateDT
	FROM @ReturnTable
	ORDER BY OrderID
GO
CREATE PROCEDURE [dbo].[deleteBOETaskElementCustomFieldValueviaTableParameter]
(
@BOETaskElementCustomFieldValueXREF [dbo].[TT_BOETaskElementCustomFieldValueXREF] READONLY
)
AS
/******************************************************************************
**		 
**		Name: [deleteBOETaskElementCustomFieldValue]
**		Desc: Deletes data from the dbo.BOETaskElementCustomFieldValueXREF table which
**				holds the Custom Field Value for the BOE Task Element
**			
**		
**
**		Auth: Don Canuso
**		Date: 2/14/11
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			---------------------------------------
**		4/1/11		dcanuso				Updated order of SP to correct for logic 
**										and updated UPDATE to handle NULL
**		7/20/11		DCANUSO				WI 4215 - Custom Fields are scope specific
**		12/15/11	dcanuso				WI 6166
**		3/8/18		ranzalon			BOEJ-3079 - Open Ended Custom Fields
*******************************************************************************/
SET NOCOUNT ON 

DELETE FROM [dbo].[BOETaskElementCustomFieldValueXREF]
	FROM [dbo].[BOETaskElementCustomFieldValueXREF] X
		INNER JOIN @BOETaskElementCustomFieldValueXREF T ON 
				X.BTECFVID = T.BTECFVID AND
				X.UpdateDT = T.UpdateDT

DELETE FROM [dbo].[CustomFieldValue]
	FROM [dbo].[CustomFieldValue] C
		INNER JOIN @BOETaskElementCustomFieldValueXREF T ON  
			C.CustomFieldValueID = T.CustomFieldValueID
	WHERE T.IsOpenEnded = 1 AND
		C.CustomFieldValueID NOT IN (SELECT CustomFieldValueID FROM [dbo].[BOETaskElementCustomFieldValueXREF])

		/*
		Only should be looking within the scope
		of the Custom Field, so if the scope is BOE
		then only look in BOECustomFieldValueXREF
		*/
		IF NOT EXISTS (SELECT [CustomFieldValueID] FROM	[BOETaskElementCustomFieldValueXREF]
						WHERE  CustomFieldValueID IN (SELECT CustomFieldValueID FROM @BOETaskElementCustomFieldValueXREF))
			BEGIN
				UPDATE dbo.CustomFieldValue
				SET CustomFieldValueInUseFlag = 0,
					UpdateDT = GETDATE()
				FROM dbo.CustomFieldValue CFV 
				WHERE CFV.CustomFieldValueID  IN (SELECT CustomFieldValueID FROM @BOETaskElementCustomFieldValueXREF WHERE IsOpenEnded = 0)
			END
GO
CREATE PROCEDURE [dbo].[updateBOETaskElementCustomFieldValueviaTableParameter]
(
@BOETaskElementCustomFieldValueXREF [dbo].[TT_BOETaskElementCustomFieldValueXREF] READONLY
)
AS
/******************************************************************************
**		 
**		Name: upsertBOETaskElementCustomFieldValue
**		Desc: Insert/Update Custom Field Value for the BOE Task Element
**			
**		
**
**		Auth: Don Canuso
**		Date: 2/14/11
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			----------------------------------------
**		7/20/11		DCANUSO				WI 4215 - Custom Fields are scope specific
**		3/8/18		ranzalon			BOEJ-3079 - Open Ended Custom Fields
*******************************************************************************/
SET NOCOUNT ON 

DECLARE @UpdateDT datetime2(7) = GetDate()
			
DECLARE @OriginalCustomFieldValue TABLE
(
	[BTECFVID] int,
	[CustomFieldValueID] int
)
INSERT INTO @OriginalCustomFieldValue
SELECT 
	[BTECFVID],
	[CustomFieldValueID]
FROM dbo.BOETaskElementCustomFieldValueXREF
WHERE 
	[BTECFVID] IN
		(
			SELECT [BTECFVID] 
			FROM @BOETaskElementCustomFieldValueXREF
			WHERE IsOpenEnded = 0
		)

UPDATE [dbo].[BOETaskElementCustomFieldValueXREF]
SET 
	[CustomFieldValueID] = T.CustomFieldValueID,
	[UpdateDT] = @UpdateDT
FROM [dbo].[BOETaskElementCustomFieldValueXREF] X
	INNER JOIN @BOETaskElementCustomFieldValueXREF T ON
			X.BTECFVID = T.BTECFVID AND
			X.UpdateDT = T.UpdateDT

UPDATE [dbo].[CustomFieldValue]
SET [CustomFieldValueDescription] = T.CustomFieldValueDescription
	,[UpdateDT] = @UpdateDT
FROM [dbo].[CustomFieldValue] C
	INNER JOIN @BOETaskElementCustomFieldValueXREF T ON
			C.CustomFieldValueID = T.CustomFieldValueID
WHERE T.IsOpenEnded = 1 AND
	EXISTS (SELECT 1 FROM [dbo].[BOETaskElementCustomFieldValueXREF]
			WHERE BTECFVID = T.BTECFVID AND UpdateDT = @UpdateDT)

/*Only should be looking within the scope
of the Custom Field, so if the scope is BOE
then only look in BOETaskElementCustomFieldValueXREF
*/
UPDATE dbo.CustomFieldValue
SET 
	CustomFieldValueInUseFlag = 
		CASE 
			WHEN X.[CustomFieldValueID] IS NULL THEN 0
			WHEN X.[CustomFieldValueID] IS NOT NULL THEN 1
		END,
		UpdateDT = @UpdateDT
FROM dbo.CustomFieldValue CFV 
LEFT OUTER JOIN [dbo].[BOETaskElementCustomFieldValueXREF] X ON
		CFV.[CustomFieldValueID] = X.[CustomFieldValueID]
WHERE 
	CFV.CustomFieldValueID IN 
		(
			SELECT DISTINCT CustomFieldValueID
			FROM @OriginalCustomFieldValue
		)

UPDATE dbo.CustomFieldValue
	SET CustomFieldValueInUseFlag = 1,
		UpdateDT = @UpdateDT
WHERE CustomFieldValueID IN
	(
		SELECT DISTINCT CustomFieldValueID
		FROM @BOETaskElementCustomFieldValueXREF
		WHERE IsOpenEnded = 0
	)
		
IF @@ERROR = 0
	SELECT	X.BTECFVID AS BTECFVID,
			X.[UpdateDT]
FROM [dbo].[BOETaskElementCustomFieldValueXREF] X
	INNER JOIN @BOETaskElementCustomFieldValueXREF T ON
			X.BTECFVID = T.BTECFVID 
ORDER BY T.OrderID
GO

/*
    File: \Table Based Processing\TaskElementViaTable.sql
*/
PRINT '### Starting file: \Table Based Processing\TaskElementViaTable.sql';
-- Drop SPs 1st
IF  EXISTS (SELECT 1 FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[updateBOETaskElementviaTableParameter]') AND type in (N'P', N'PC'))
	DROP PROCEDURE [dbo].[updateBOETaskElementviaTableParameter];
GO
IF  EXISTS (SELECT 1 FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[deleteBOETaskElementviaTableParameter]') AND type in (N'P', N'PC'))
	DROP PROCEDURE [dbo].[deleteBOETaskElementviaTableParameter];
GO
IF  EXISTS (SELECT 1 FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[insertBOETaskElementviaTableParameter]') AND type in (N'P', N'PC'))
	DROP PROCEDURE [dbo].[insertBOETaskElementviaTableParameter];
GO

-- Drop types 2nd
IF  EXISTS (SELECT 1 FROM sys.types st JOIN sys.schemas ss ON st.schema_id = ss.schema_id WHERE st.name = N'TT_BOETaskElement' AND ss.name = N'dbo')
	DROP TYPE [dbo].[TT_BOETaskElement];
GO

-- Recreate types 3rd
CREATE TYPE [dbo].[TT_BOETaskElement] AS TABLE(
	[BOETaskElementID] [int] PRIMARY KEY CLUSTERED,
	[UpdateDT] [datetime2](7) NOT NULL,
	[TaskID] [varchar](3) NULL,
	[TaskTitle] [varchar](100) NOT NULL,
	[TaskDescription] [varchar](max) NULL,
	[TaskStartDate] [date] NULL,
	[TaskEndDate] [date] NULL,
	[MOQHoursEquation] [varchar](500) NULL,
	[MOQCostEquation] [varchar](250) NULL,
	[MOQText] [varchar](max) NULL,
	[MOQTypeID] [int] NULL,
	[BOEID] [int] NOT NULL,
	[LaborTypeWarningFlag] [bit] NOT NULL,
	[IMS_ID] [varchar](20) NULL,
	[TaskElementTypeID] [int] NOT NULL,
	[SortOrderID] [int] NOT NULL,
	/* OrderID is automatically added in the code, so it HAS to be last */
	[OrderID] [int] NOT NULL
);
GO

-- Recreate SPs last
SET ANSI_NULLS OFF
GO
SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[updateBOETaskElementviaTableParameter]
(
@BOETaskElement [dbo].[TT_BOETaskElement] READONLY
)
AS
/******************************************************************************
**		 
**		Name: [upsertBOETaskElement]
**		Desc: Insert/Update data into BOE Task Elements Detailed Section of BOE
**			
**		
**
**		Auth: Don Canuso
**		Date: 8/2010
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			-------------------------------------------
**      1/17/17		twilson3			BOEJ-1604 Cleanup DB Project
**		1/26/17		pattoncr			Updating MOQHoursEquation to varchar(500).
**		12/7/17		twilson3			BOEJ-1994 - Remove Summary BOE
**		1/16/18		twilson3			BOEJ-2887 Remove Historical Metrics
**		6/25/19		twilson3			BOEJ-3964 - Remove in-use flag, MaterialXref
*******************************************************************************/
SET NOCOUNT ON 

DECLARE @UpdateDT datetime2 = GETDATE()

SET @UpdateDT = GetDate()
			
			 
UPDATE [dbo].[BOETaskElement]
	SET 
		[TaskID] = TT.TaskID,
		[TaskTitle] = TT.TaskTitle,
		[TaskDescription] = TT.TaskDescription,
		[TaskStartDate] = TT.TaskStartDate,
		[TaskEndDate] = TT.TaskEndDate,
		[MOQHoursEquation] = TT.MOQHoursEquation,
		[MOQCostEquation] = TT.MOQCostEquation,
		[MOQText] = TT.MOQText,
		[MOQTypeID] = TT.MOQTypeID,
		[BOEID] = TT.BOEID,
		[LaborTypeWarningFlag] = TT.LaborTypeWarningFlag,
		[IMS_ID] = TT.IMS_ID,
		[TaskElementTypeID] = TT.TaskElementTypeID,
		[UpdateDT] = @UpdateDT,
		[SortOrderID] = TT.SortOrderID
FROM [dbo].[BOETaskElement] TE
	INNER JOIN @BOETaskElement TT ON 
		TE.BOETaskElementID = TT.BOETaskElementID AND
		TE.UpdateDT = TT.UpdateDT
				
IF @@ERROR = 0
	SELECT 
		T.BOETaskElementID AS BOETaskElementID, 
		T.UpdateDT AS UpdateDT 
	FROM @BOETaskElement TT
		INNER JOIN dbo.BOETaskElement T ON TT.BOETaskElementID = T.BOETaskElementID
	ORDER BY OrderID
GO
CREATE PROCEDURE [dbo].[deleteBOETaskElementviaTableParameter]
(
@BOETaskElement [dbo].[TT_BOETaskElement] READONLY
)
AS
/******************************************************************************
**		 
**		Name: [deleteBOETaskElementviaTableParameter]
**		Desc: Delete Flag set in LM Task Element Section of BOE and all sub-elements (Labor Types and Labor Spread)
**			
**		
**
**		Auth: Don Canuso
**		Date: 8/2010
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			-------------------------------------------
**      6/24/16     twilson3            Fix In-Use Flag for Custom Fields
**		1/16/18		twilson3			BOEJ-2887 Remove Historical Metrics
**		4/2/18		ranzalon			BOEJ-3268 - Update for Open Ended Custom Fields
*******************************************************************************/
SET NOCOUNT ON 


			DELETE FROM dbo.BOELaborSpread
				FROM dbo.BOELaborSpread LS
				INNER JOIN dbo.BOELaborType LT ON LS.BOELaborTypeID = LT.BOELaborTypeID
				INNER JOIN dbo.BOETaskElement TE ON LT.BOETaskElementID = TE.BOETaskElementID
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT
			
			--Get Custom Field Value IDs before the xrefs are deleted
			DECLARE @LaborTypeCustomFieldXrefs TABLE (CustomFieldValueID int)

			INSERT INTO @LaborTypeCustomFieldXrefs
			SELECT CustomFieldValueID
			FROM dbo.BOELaborTypeCustomFieldValueXREF
			WHERE BOELaborTypeID IN
				(
					SELECT BOELaborTypeID
					FROM dbo.BOELaborType LT
					INNER JOIN @BOETaskElement TT ON 
					LT.BOETaskElementID = TT.BOETaskElementID
				)	
			
			DELETE FROM dbo.BOELaborTypeCustomFieldValueXREF
			FROM dbo.BOELaborTypeCustomFieldValueXREF X
				INNER JOIN dbo.BOELaborType LT ON X.BOELaborTypeID = LT.BOELaborTypeID
				INNER JOIN dbo.BOETaskElement TE ON LT.BOETaskElementID = TE.BOETaskElementID
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT
				
			--Delete Custom Field Values for deleted Open Ended Custom Fields
			DELETE FROM dbo.CustomFieldValue
			WHERE CustomFieldValueID in
			(
				SELECT x.CustomFieldValueID
				FROM @LaborTypeCustomFieldXrefs x
				JOIN dbo.CustomFieldValue v on x.CustomFieldValueID = v.CustomFieldValueID
				JOIN dbo.CustomField c on v.CustomFieldId = c.CustomFieldID
				WHERE c.IsOpenEnded = 1
			)
				
			DELETE FROM dbo.BOETaskElementWorkspaceVariableXREF
			FROM dbo.BOETaskElementWorkspaceVariableXREF X  
				INNER JOIN dbo.BOETaskElement TE ON X.BOETaskElementID = TE.BOETaskElementID
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT

				
			DELETE FROM dbo.SumOfBOE_OrdinaryVariableXREF
			FROM  dbo.SumOfBOE_OrdinaryVariableXREF X
				INNER JOIN dbo.OrdinaryVariable OV ON X.OrdinaryVariableID = OV.OrdinaryVariableID
				INNER JOIN  dbo.BOETaskElement TE ON OV.BOETaskElementID = TE.BOETaskElementID
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT

			

			DELETE FROM dbo.OrdinaryVariableSumVariableResourceTypeXREF
			FROM dbo.OrdinaryVariableSumVariableResourceTypeXREF X
				INNER JOIN dbo.OrdinaryVariable OV ON X.OrdinaryVariableID = OV.OrdinaryVariableID
				INNER JOIN  dbo.BOETaskElement TE ON OV.BOETaskElementID = TE.BOETaskElementID
							INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT


				

			DELETE FROM dbo.OrdinaryVariable
			FROM dbo.OrdinaryVariable OV
				INNER JOIN dbo.BOETaskElement TE ON OV.BOETaskElementID = TE.BOETaskElementID
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT

			--Get Custom Field Value IDs before the xrefs are deleted
			DECLARE @TaskCustomFieldXrefs TABLE (CustomFieldValueID int)

			INSERT INTO @TaskCustomFieldXrefs
			SELECT CustomFieldValueID
			FROM dbo.BOETaskElementCustomFieldValueXREF
			WHERE BOETaskElementID IN
			(
				SELECT BOETaskElementID
				FROM @BOETaskElement
			)
				
			DELETE FROM dbo.BOETaskElementCustomFieldValueXREF
			FROM dbo.BOETaskElementCustomFieldValueXREF X 
				INNER JOIN dbo.BOETaskElement TE ON X.BOETaskElementID = TE.BOETaskElementID 
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT

			--Delete Custom Field Values for deleted Open Ended Custom Fields
			DELETE FROM dbo.CustomFieldValue
			WHERE CustomFieldValueID in
			(
				SELECT x.CustomFieldValueID
				FROM @TaskCustomFieldXrefs x
				JOIN dbo.CustomFieldValue v on x.CustomFieldValueID = v.CustomFieldValueID
				JOIN dbo.CustomField c on v.CustomFieldId = c.CustomFieldID
				WHERE c.IsOpenEnded = 1
			)
			
			DELETE FROM [dbo].[BOETaskElementMetricDetailXREF]
				FROM [dbo].[BOETaskElementMetricDetailXREF] X 
				INNER JOIN dbo.BOETaskElement TE ON X.BOETaskElementID = TE.BOETaskElementID 
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT


			
 
			DELETE FROM dbo.BOELaborType
				FROM dbo.BOELaborType LT
				INNER JOIN dbo.BOETaskElement TE ON LT.BOETaskElementID = TE.BOETaskElementID
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT

				
				
			DECLARE @WorkspaceID int
			SELECT @WorkspaceID = WorkspaceID 
			FROM dbo.BOE B
				INNER JOIN dbo.BOETaskElement TE ON B.BOEID = TE.BOEID
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT


			
				
			DELETE FROM [dbo].[BOETaskElement]
			FROM [dbo].[BOETaskElement] TE
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT



IF @@ERROR <> 0
BEGIN
DECLARE @ErrorMessage varchar (500)
SET @ErrorMessage =   'The BOE Task Element(s) has been updated and is out of sync with the data in your browser.  Please refresh your data.'
			RAISERROR (
					@ErrorMessage, -- Message text.
					11, -- Severity,/*Severity Changed to 11*/
					1 -- State,
					)
			RETURN
 
		END
GO
CREATE PROCEDURE [dbo].[insertBOETaskElementviaTableParameter]
(
@BOETaskElement [dbo].[TT_BOETaskElement] READONLY
)
AS
/******************************************************************************
**		 
**		Name: [upsertBOETaskElement]
**		Desc: Insert/Update data into BOE Task Elements Detailed Section of BOE
**			
**		
**
**		Auth: Don Canuso
**		Date: 8/2010
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			-------------------------------------------
**		1/26/17		pattoncr			Updating MOQHoursEquation to varchar(500)
**		12/7/17		twilson3			BOEJ-1994 - Remove Summary BOE
**		1/16/18		twilson3			BOEJ-2887 Remove Historical Metrics
*******************************************************************************/
	SET NOCOUNT ON 
	DECLARE @UpdateDT datetime2 = GETDATE()
	DECLARE @TT_BOETaskElement TABLE
	(
		[BOETaskElementID] [int] NOT NULL,
		[UpdateDT] [datetime2](7) NOT NULL,
		[TaskID] [varchar](3) NULL,
		[TaskTitle] [varchar](100) NOT NULL,
		[TaskDescription] [varchar](max) NULL,
		[TaskStartDate] [date] NULL,
		[TaskEndDate] [date] NULL,
		[MOQHoursEquation] [varchar](500) NULL,
		[MOQCostEquation] [varchar](250) NULL,
		[MOQText] [varchar](max) NULL,
		[MOQTypeID] [int] NULL,
		[BOEID] [int] NOT NULL,
		[LaborTypeWarningFlag] [bit] NOT NULL,
		[IMS_ID] [varchar](20) NULL,
		[TaskElementTypeID] [int] NOT NULL,
		[SortOrderID] [int] NOT NULL,
		/* OrderID is automatically added in the code, so it HAS to be last */
		[OrderID] [int] NOT NULL
	)
	DECLARE @BOETaskElementID [int],
		@TaskID [varchar](3),
		@TaskTitle [varchar](100),
		@TaskDescription[varchar](max),
		@TaskStartDate [date],
		@TaskEndDate [date],
		@MOQHoursEquation [varchar](500),
		@MOQCostEquation [varchar](250),
		@MOQText [varchar](max),
		@MOQTypeID [int],
		@BOEID [int],
		@LaborTypeWarningFlag [bit],
		@IMS_ID [varchar](20),
		@TaskElementTypeID [int],
		@OrderID [int],
		@SortOrderID [int]
	DECLARE @InsertedBOETaskElement AS Table (BOETaskElementID int)
	INSERT INTO @TT_BOETaskElement SELECT * FROM @BOETaskElement

	WHILE EXISTS (SELECT 1 FROM @TT_BOETaskElement WHERE BOETaskElementID < 0)
		BEGIN
			SELECT TOP 1 
				@BOETaskElementID = BOETaskElementID,
				@TaskID = TaskID,
				@TaskTitle = TaskTitle,
				@TaskDescription = TaskDescription,
				@TaskStartDate = TaskStartDate,
				@TaskEndDate = TaskEndDate,
				@MOQHoursEquation = MOQHoursEquation,
				@MOQCostEquation = MOQCostEquation,
				@MOQText = MOQText,
				@MOQTypeID = MOQTypeID,
				@BOEID = BOEID,
				@LaborTypeWarningFlag = LaborTypeWarningFlag,
				@IMS_ID = IMS_ID,
				@TaskElementTypeID = TaskElementTypeID,
				@OrderID =  OrderID,
				@SortOrderID = SortOrderID
			FROM @TT_BOETaskElement
			WHERE BOETaskElementID < 0
			INSERT INTO [dbo].[BOETaskElement]
				   ([TaskID]
				   ,[TaskTitle]
				   ,[TaskDescription]
				   ,[TaskStartDate]
				   ,[TaskEndDate]
				   ,[MOQHoursEquation]
				   ,[MOQCostEquation]
				   ,[MOQText]
				   ,[MOQTypeID]
				   ,[BOEID]
				   ,[LaborTypeWarningFlag]
				   ,[IMS_ID]
				   ,[TaskElementTypeID]
				   ,[UpdateDT]
				   ,[SortOrderID]
				   )
			 OUTPUT inserted.BOETaskElementID INTO @InsertedBOETaskElement
			 VALUES
				   (
					@TaskID
				   ,@TaskTitle
				   ,@TaskDescription
				   ,@TaskStartDate
				   ,@TaskEndDate
				   ,@MOQHoursEquation
				   ,@MOQCostEquation
				   ,@MOQText
				   ,@MOQTypeID
				   ,@BOEID
				   ,@LaborTypeWarningFlag
				   ,@IMS_ID
				   ,@TaskElementTypeID
				   ,@UpdateDT
				   ,@SortOrderID
					) 
			SELECT @BOETaskElementID = BOETaskElementID FROM @InsertedBOETaskElement
	
			UPDATE @TT_BOETaskElement
				SET BOETaskElementID = @BOETaskElementID
			WHERE 
				@OrderID = OrderID AND
				BOETaskElementID < 0
		END

	IF @@ERROR = 0
		SELECT 
			TT.BOETaskElementID AS BOETaskElementID, 
			@UpdateDT AS UpdateDT
		FROM @TT_BOETaskElement TT
			ORDER BY OrderID
GO

/*
    File: \Table Based Processing\TaskElementWorkspaceVariableViaTable.sql
*/
PRINT '### Starting file: \Table Based Processing\TaskElementWorkspaceVariableViaTable.sql';
-- Drop SPs first
IF  EXISTS (SELECT 1 FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[insertBOETaskElementWorkspaceVariableviaTableParameter]') AND type in (N'P', N'PC'))
	DROP PROCEDURE [dbo].[insertBOETaskElementWorkspaceVariableviaTableParameter];
GO

-- Drop types 2nd
IF  EXISTS (SELECT * FROM sys.types st JOIN sys.schemas ss ON st.schema_id = ss.schema_id WHERE st.name = N'TT_BOETaskElementWorkspaceVariableXREF' AND ss.name = N'dbo')
	DROP TYPE [dbo].[TT_BOETaskElementWorkspaceVariableXREF];
