CREATE TYPE [dbo].[TT_BOETaskElementWorkspaceVariableXREF] AS TABLE(
	[BOETaskWSVarID] [int] NOT NULL,
	[BOETaskElementID] [int] NOT NULL,
	[WorkspaceVariableID] [int] NOT NULL,
	[OrderID] [int] NOT NULL
);
